export default App;

export enum AppMode {
  SELECT = 'SELECT',
  WEARABLE = 'WEARABLE',
  COMPANION = 'COMPANION',
}

export interface VitalSigns {
  timestamp: number;
  heartRate: number; // bpm
  spo2: number; // %
  temperature: number; // Celsius
  systolic: number; // mmHg
  diastolic: number; // mmHg
  steps: number;
  stressLevel: number; // 0-100
  isSleeping: boolean;
  accelerometer: {
    x: number;
    y: number;
    z: number;
  };
}

export interface EmergencyContact {
