}

export interface HealthAnalysis {
  status: 'NORMAL' | 'WARNING' | 'CRITICAL';
  summary: string;
  recommendation: string;
  anomaliesDetected: string[];
}

// For BroadcastChannel communication
export interface SyncMessage {
  type: 'VITALS_UPDATE' | 'EMERGENCY_TRIGGER' | 'ANALYSIS_UPDATE' | 'FALL_DETECTED';
  payload: any;
}

import { GoogleGenAI, Type } from "@google/genai";
import { VitalSigns, HealthAnalysis } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeVitals = async (history: VitalSigns[]): Promise<HealthAnalysis> => {
  if (!process.env.API_KEY) {
    return {
      status: 'NORMAL',
      summary: 'API Key missing. Cannot perform AI analysis.',
      recommendation: 'Please configure the environment.',
      anomaliesDetected: [],
    };
  }

  const recentHistory = history.slice(-20);

  const prompt = `
    Analyze the following time-series health data collected from a wearable device.
    Determine the user's health status, identify any patterns, and detect anomalies.

    Data Context:
    - Resting Heart Rate: Normal is 60-100 bpm.
    - SpO2: Below 95% is concerning.
    - Body Temperature: Normal is 36.1C - 37.2C. Above 38C is fever.
    - Blood Pressure: Normal is around 120/80 mmHg. 
      - Hypertension: Systolic > 140 or Diastolic > 90.
      - Hypotension: Systolic < 90 or Diastolic < 60.
    - Stress Level: > 80 is high.

    Task:
    1. Analyze trends in Heart Rate, Blood Pressure, and Temperature.
    2. Check for correlation between vitals (e.g., rising temp + high HR = possible infection).
    3. Flag specific anomalies.

    Data: ${JSON.stringify(recentHistory)}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ['NORMAL', 'WARNING', 'CRITICAL'] },
            summary: { type: Type.STRING },
            recommendation: { type: Type.STRING },
            anomaliesDetected: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ['status', 'summary', 'recommendation', 'anomaliesDetected']
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as HealthAnalysis;

  } catch (error) {
    console.error("AI Analysis Failed:", error);
    return {
      status: 'WARNING',
      summary: 'Unable to connect to AI Analysis service.',
      recommendation: 'Check network connection.',
      anomaliesDetected: ['AI Service Unavailable']
    };
  }
};

/**
 * Uses Gemini to analyze accelerometer sequences for fall patterns.
 * A fall typically involves: 
 * 1. High acceleration (descent) 
 * 2. Sudden impact (spike)
 * 3. Immediate relative stillness or odd orientation.
 */
export const detectFalls = async (history: VitalSigns[]): Promise<boolean> => {
  if (!process.env.API_KEY || history.length < 5) return false;

  // We only need the accelerometer part for this specific detection
  const accelData = history.slice(-10).map(v => ({
    ts: v.timestamp,
    ...v.accelerometer
  }));

  const prompt = `
    Analyze the following 10-point sequence of accelerometer data (x, y, z in m/s^2) from a wearable device.
    Determine if the sequence represents a significant fall event.

    Normal standing/walking has Z around 9.8 and small variations in X/Y.
    A fall is characterized by a sudden change in magnitude (resultant vector), usually a spike above 20 m/s^2 (impact) followed by low movement or a changed static orientation.

    Data: ${JSON.stringify(accelData)}

    Respond in JSON format.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isFallDetected: { type: Type.BOOLEAN, description: "True if a fall pattern is identified." },
            confidence: { type: Type.NUMBER, description: "Confidence score 0-1" }
          },
          required: ['isFallDetected']
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return !!result.isFallDetected;
  } catch (error) {
    console.error("Fall detection error:", error);
    return false;
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
