import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AppMode, VitalSigns, EmergencyContact, HealthAnalysis, SyncMessage } from './types';
import WearableInterface from './components/WearableInterface';
import CompanionDashboard from './components/CompanionDashboard';
import { analyzeVitals, detectFalls } from './services/geminiService';

const BROADCAST_CHANNEL_NAME = 'vitals_sync_channel';

const INITIAL_VITALS: VitalSigns = {
  timestamp: Date.now(),
  heartRate: 75,
  spo2: 98,
  temperature: 36.6,
  systolic: 120,
  diastolic: 80,
  steps: 1240,
  stressLevel: 25,
  isSleeping: false,
  isScanning: false,
  accelerometer: { x: 0, y: 0.2, z: 9.8 }
};

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.SELECT);
  const [vitals, setVitals] = useState<VitalSigns>(INITIAL_VITALS);
  const [history, setHistory] = useState<VitalSigns[]>([INITIAL_VITALS]);
  const [emergencyContacts, setEmergencyContacts] = useState<EmergencyContact[]>([
    { id: '1', name: 'Emergency Services', phone: '911', isAutoDial: true }
  ]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [analysis, setAnalysis] = useState<HealthAnalysis | null>(null);
  const [isAnalysing, setIsAnalysing] = useState(false);

  const channelRef = useRef<BroadcastChannel | null>(null);

  useEffect(() => {
    channelRef.current = new BroadcastChannel(BROADCAST_CHANNEL_NAME);

    channelRef.current.onmessage = (event) => {
      const message: SyncMessage = event.data;
      if (message.type === 'VITALS_UPDATE') {
        const newVitals = message.payload;
        setVitals(newVitals);
        setHistory(prev => [...prev, newVitals].slice(-500)); // Larger history for logging
      } else if (message.type === 'EMERGENCY_TRIGGER' || message.type === 'SOS_TRIGGER') {
        setIsEmergency(message.payload);
      } else if (message.type === 'ANALYSIS_UPDATE') {
        setAnalysis(message.payload);
      } else if (message.type === 'FALL_DETECTED') {
        setIsEmergency(true);
      }
    };

    return () => channelRef.current?.close();
  }, []);

  const broadcast = useCallback((type: SyncMessage['type'], payload: any) => {
    channelRef.current?.postMessage({ type, payload });
  }, []);

  // Automated Analysis Trigger
  useEffect(() => {
    if (mode === AppMode.COMPANION && history.length > 10 && !isAnalysing) {
      const lastVitals = vitals;
      const needsReview = lastVitals.heartRate > 120 || lastVitals.spo2 < 95 || lastVitals.temperature > 38;

      if (needsReview) {
        handleTriggerAnalysis();
      }
    }
  }, [vitals.heartRate, vitals.spo2, vitals.temperature, mode]);

  // Wearable Simulation Logic
  useEffect(() => {
    if (mode !== AppMode.WEARABLE) return;

    const interval = setInterval(() => {
      setVitals(prev => {
        const jitter = (base: number, range: number) => base + (Math.random() * range - range/2);

        const isAnomaly = prev.heartRate > 130 || prev.spo2 < 92 || prev.temperature > 38 || prev.systolic > 145;

        let newHr = isAnomaly ? jitter(prev.heartRate, 3) : jitter(75, 5);
        let newSpo2 = isAnomaly ? jitter(prev.spo2, 0.5) : jitter(98, 1);
        let newTemp = isAnomaly ? jitter(prev.temperature, 0.1) : jitter(36.6, 0.2);
        let newSys = isAnomaly ? jitter(prev.systolic, 2) : jitter(120, 4);
        let newDia = isAnomaly ? jitter(prev.diastolic, 1) : jitter(80, 2);

        let newAccel = { x: jitter(0, 0.5), y: jitter(0.2, 0.5), z: jitter(9.8, 0.2) };

        if(newSpo2 > 100) newSpo2 = 100;

        const newVitals: VitalSigns = {
          ...prev,
          timestamp: Date.now(),
          heartRate: Math.round(newHr),
          spo2: Math.round(newSpo2),
          temperature: newTemp,
          systolic: Math.round(newSys),
          diastolic: Math.round(newDia),
          stressLevel: Math.round(Math.max(0, Math.min(100, jitter(isAnomaly ? 85 : 25, 5)))),
          steps: prev.isSleeping ? prev.steps : prev.steps + (Math.random() > 0.8 ? 1 : 0),
          accelerometer: newAccel
        };

        const isCritical = (newVitals.heartRate > 155 && newVitals.spo2 < 90) || (newVitals.systolic > 185);

        if (isCritical && !isEmergency) {
             setIsEmergency(true);
             broadcast('EMERGENCY_TRIGGER', true);
        }

        broadcast('VITALS_UPDATE', newVitals);
        return newVitals;
      });
    }, 2000);

    return () => clearInterval(interval);
  }, [mode, broadcast, isEmergency]);

  // Handlers
  const handleToggleSleep = () => {
    setVitals(prev => {
      const newVal = { ...prev, isSleeping: !prev.isSleeping };
      broadcast('VITALS_UPDATE', newVal);
      return newVal;
    });
  };

  const handleToggleScan = () => {
    setVitals(prev => {
      const newVal = { ...prev, isScanning: !prev.isScanning };
      broadcast('VITALS_UPDATE', newVal);
      return newVal;
    });
  };

  const handleTriggerSOS = () => {
    setIsEmergency(true);
    broadcast('SOS_TRIGGER', true);
  };

  const handleSimulateAnomaly = () => {
    setVitals(prev => {
      const newVal = { 
        ...prev, 
        heartRate: 155, 
        stressLevel: 98,
        accelerometer: { x: 32.1, y: -18.5, z: 1.2 }
      };
      broadcast('VITALS_UPDATE', newVal);
      return newVal;
    });
  };

  const handleCancelEmergency = () => {
    setIsEmergency(false);
    broadcast('EMERGENCY_TRIGGER', false);
    setVitals(prev => {
        const newVal = { ...INITIAL_VITALS, timestamp: Date.now(), steps: prev.steps };
        broadcast('VITALS_UPDATE', newVal);
        return newVal;
    });
  };

  const handleTriggerAnalysis = async () => {
    if (history.length < 5 || isAnalysing) return;
    setIsAnalysing(true);
    const result = await analyzeVitals(history);
    setAnalysis(result);
    broadcast('ANALYSIS_UPDATE', result);
    setIsAnalysing(false);
  };

  const handleAddContact = (contact: EmergencyContact) => setEmergencyContacts(prev => [...prev, contact]);
  const handleRemoveContact = (id: string) => setEmergencyContacts(prev => prev.filter(c => c.id !== id));
  const handleToggleAutoDial = (id: string) => {
    setEmergencyContacts(prev => prev.map(c => c.id === id ? { ...c, isAutoDial: !c.isAutoDial } : c));
  };

  if (mode === AppMode.SELECT) {
    return (
      <div className="min-h-screen bg-gray-950 flex flex-col items-center justify-center p-6">
        <div className="mb-12 text-center">
          <h1 className="text-5xl md:text-7xl font-black bg-clip-text text-transparent bg-gradient-to-br from-cyan-400 via-blue-500 to-purple-600 mb-4 tracking-tighter">
            VitalSync AI
          </h1>
          <p className="text-gray-500 font-bold uppercase tracking-[0.2em] text-xs">Biometric Intelligence & Protection</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl">
          <button 
            onClick={() => setMode(AppMode.WEARABLE)}
            className="group relative bg-gray-900 border border-gray-800 hover:border-cyan-500/50 rounded-[2.5rem] p-10 transition-all hover:translate-y-[-8px] shadow-2xl"
          >
            <div className="absolute top-0 right-0 p-6 opacity-20 group-hover:opacity-100 transition-opacity">
               <i className="fas fa-microchip text-4xl text-cyan-500"></i>
            </div>
            <div className="flex flex-col items-start gap-6">
              <div className="w-16 h-16 rounded-3xl bg-cyan-500/10 flex items-center justify-center text-3xl text-cyan-400">
                <i className="fas fa-clock"></i>
              </div>
              <div className="text-left">
                <h2 className="text-3xl font-black text-white mb-2 uppercase tracking-tighter">Bio-Watch</h2>
                <p className="text-gray-500 text-sm leading-relaxed font-medium">
                  Smartwatch simulation with live Pulse Scan, Fall Detection, and manual SOS trigger.
                </p>
              </div>
            </div>
          </button>

          <button 
            onClick={() => setMode(AppMode.COMPANION)}
            className="group relative bg-gray-900 border border-gray-800 hover:border-blue-500/50 rounded-[2.5rem] p-10 transition-all hover:translate-y-[-8px] shadow-2xl"
          >
             <div className="absolute top-0 right-0 p-6 opacity-20 group-hover:opacity-100 transition-opacity">
               <i className="fas fa-network-wired text-4xl text-blue-500"></i>
            </div>
            <div className="flex flex-col items-start gap-6">
              <div className="w-16 h-16 rounded-3xl bg-blue-500/10 flex items-center justify-center text-3xl text-blue-400">
                <i className="fas fa-laptop-medical"></i>
              </div>
              <div className="text-left">
                <h2 className="text-3xl font-black text-white mb-2 uppercase tracking-tighter">Guardian Hub</h2>
                <p className="text-gray-500 text-sm leading-relaxed font-medium">
                  Central dashboard with deep historical logs, trend analysis, and Gemini health insights.
                </p>
              </div>
            </div>
          </button>
        </div>

        <div className="mt-16 flex items-center gap-4 text-gray-700 font-bold uppercase text-[10px] tracking-widest bg-gray-900/50 px-6 py-3 rounded-full border border-gray-800">
           <i className="fas fa-broadcast-tower animate-pulse text-cyan-500"></i> 
           Local Sync Engine v2.5 Running
        </div>
      </div>
    );
  }

  if (mode === AppMode.WEARABLE) {
    return (
      <WearableInterface 
        currentVitals={vitals}
        onToggleSleep={handleToggleSleep}
        onToggleScan={handleToggleScan}
        onSimulateAnomaly={handleSimulateAnomaly}
        isEmergency={isEmergency}
        onCancelEmergency={handleCancelEmergency}
        onTriggerSOS={handleTriggerSOS}
      />
    );
  }

  return (
    <CompanionDashboard 
       vitalsHistory={history}
       currentVitals={vitals}
       analysis={analysis}
       emergencyContacts={emergencyContacts}
       onAddContact={handleAddContact}
       onRemoveContact={handleRemoveContact}
       onToggleAutoDial={handleToggleAutoDial}
       isAnalysing={isAnalysing}
       onTriggerAnalysis={handleTriggerAnalysis}
    />
  );
};

export default App;

