import { GoogleGenAI, Type } from "@google/genai";
import { VitalSigns, HealthAnalysis, Patient } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzePatientHealth = async (patient: Patient): Promise<HealthAnalysis> => {
  if (!process.env.API_KEY) {
    return {
      status: 'NORMAL',
      summary: 'API Key missing.',
      recommendation: 'Configure API Key.',
      anomaliesDetected: [],
    };
  }

  const recentVitals = patient.history.slice(-15);

  const prompt = `
    You are the "VitalSync AI Agent". You are monitoring patient: ${patient.name} (${patient.age}y, ${patient.gender}).
    Your role is PROACTIVE INTERVENTION. 

    Current Vitals: ${JSON.stringify(patient.vitals)}
    Recent History: ${JSON.stringify(recentVitals)}

    Assess the situation. If you detect a trend (not just a single point spike), decide on an AGENT ACTION.
    Agent Actions could be: "Increasing sampling rate", "Initiating Emergency Protocol", "Requesting user verification", "No action needed".

    Respond in JSON format.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ['NORMAL', 'WARNING', 'CRITICAL'] },
            summary: { type: Type.STRING },
            recommendation: { type: Type.STRING },
            anomaliesDetected: { type: Type.ARRAY, items: { type: Type.STRING } },
            agentActions: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ['status', 'summary', 'recommendation', 'anomaliesDetected', 'agentActions']
        }
      }
    });

    return JSON.parse(response.text || "{}") as HealthAnalysis;
  } catch (error) {
    console.error("Agent Analysis Error:", error);
    return {
      status: 'WARNING',
      summary: 'Agent connectivity interrupted.',
      recommendation: 'Manual monitoring advised.',
      anomaliesDetected: ['Agent Offline'],
      agentActions: ['Attempting reconnection']
    };
  }
};

export const detectFalls = async (history: VitalSigns[]): Promise<boolean> => {
  if (!process.env.API_KEY || history.length < 5) return false;
  const accelData = history.slice(-10).map(v => v.accelerometer);

  const prompt = `Analyze this accelerometer sequence: ${JSON.stringify(accelData)}. Was there a fall? Respond with a JSON boolean "isFallDetected".`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: { isFallDetected: { type: Type.BOOLEAN } },
          required: ['isFallDetected']
        }
      }
    });
    return !!JSON.parse(response.text || "{}").isFallDetected;
  } catch { return false; }
};

