const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.SELECT);
  const [patients, setPatients] = useState<Patient[]>(DEFAULT_PATIENTS);
  const [activePatientId, setActivePatientId] = useState<string>(DEFAULT_PATIENTS[0].id);
  const [isEmergency, setIsEmergency] = useState(false);
  const [isAnalysing, setIsAnalysing] = useState(false);

  const channelRef = useRef<BroadcastChannel | null>(null);

  useEffect(() => {
    channelRef.current = new BroadcastChannel(BROADCAST_CHANNEL_NAME);
    channelRef.current.onmessage = (event) => {
      const msg: SyncMessage = event.data;
      if (msg.type === 'PATIENT_UPDATE') {
        setPatients(prev => prev.map(p => p.id === msg.payload.id ? msg.payload : p));
      } else if (msg.type === 'SOS_TRIGGER') {
        setIsEmergency(msg.payload);
      }
    };
    return () => channelRef.current?.close();
  }, []);

  const broadcast = useCallback((type: SyncMessage['type'], payload: any) => {
    channelRef.current?.postMessage({ type, payload });
  }, []);

  // Agentic Loop: Auto-Analysis
  useEffect(() => {
    const activePatient = patients.find(p => p.id === activePatientId);
    if (!activePatient || isAnalysing) return;

    const criticalThreshold = activePatient.vitals.heartRate > 120 || activePatient.vitals.spo2 < 92;
    if (criticalThreshold) {
      handleTriggerAnalysis();
    }
  }, [activePatientId, patients]);

  // Data Generation (Wearable Mode)
  useEffect(() => {
    if (mode !== AppMode.WEARABLE) return;

    const interval = setInterval(() => {
      setPatients(prev => {
        return prev.map(p => {
          if (p.id !== activePatientId) return p;

          const jitter = (b: number, r: number) => b + (Math.random() * r - r/2);
          const isAnomaly = p.vitals.heartRate > 110;

          const newVitals: VitalSigns = {
            ...p.vitals,
            timestamp: Date.now(),
            heartRate: Math.round(isAnomaly ? jitter(p.vitals.heartRate, 4) : jitter(72, 6)),
            spo2: Math.max(90, Math.min(100, Math.round(jitter(p.vitals.spo2, 1)))),
            temperature: jitter(36.6, 0.4),
            steps: p.vitals.isSleeping ? p.vitals.steps : p.vitals.steps + (Math.random() > 0.9 ? 1 : 0),
          };

          const updatedPatient = {
            ...p,
            vitals: newVitals,
            history: [...p.history, newVitals].slice(-200)
          };

          broadcast('PATIENT_UPDATE', updatedPatient);
          return updatedPatient;
        });
      });
    }, 2000);

    return () => clearInterval(interval);
  }, [mode, activePatientId, broadcast]);

  const handleTriggerAnalysis = async () => {
    const activePatient = patients.find(p => p.id === activePatientId);
    if (!activePatient || isAnalysing) return;

    setIsAnalysing(true);
    const result = await analyzePatientHealth(activePatient);

    setPatients(prev => prev.map(p => {
      if (p.id !== activePatientId) return p;
      const updated = { ...p, analysis: result };
      broadcast('PATIENT_UPDATE', updated);
      return updated;
    }));
    setIsAnalysing(false);
  };

  const currentPatient = patients.find(p => p.id === activePatientId) || patients[0];

  if (mode === AppMode.SELECT) {
    return (
      <div className="min-h-screen bg-gray-950 flex flex-col items-center justify-center p-8">
        <div className="text-center mb-16">
          <h1 className="text-6xl font-black bg-clip-text text-transparent bg-gradient-to-r from-cyan-400 to-blue-600 mb-4 tracking-tighter italic">VITALSYNC AI</h1>
          <p className="text-gray-500 font-bold uppercase tracking-[0.3em] text-[10px]">Real-time Health Agent Infrastructure</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl">
          <button onClick={() => setMode(AppMode.WEARABLE)} className="bg-gray-900/50 p-12 rounded-[3rem] border border-gray-800 hover:border-cyan-500/50 transition-all hover:-translate-y-2 group shadow-2xl">
             <i className="fas fa-clock text-4xl text-cyan-500 mb-6 group-hover:scale-110 transition-transform"></i>
             <h3 className="text-2xl font-black uppercase mb-2">Wearable Node</h3>
             <p className="text-gray-500 text-sm">Deploy as a biometric collection device. Supports live pulse scanning and fall detection.</p>
          </button>
          <button onClick={() => setMode(AppMode.COMPANION)} className="bg-gray-900/50 p-12 rounded-[3rem] border border-gray-800 hover:border-blue-500/50 transition-all hover:-translate-y-2 group shadow-2xl">
             <i className="fas fa-desktop text-4xl text-blue-500 mb-6 group-hover:scale-110 transition-transform"></i>
             <h3 className="text-2xl font-black uppercase mb-2">Command Hub</h3>
             <p className="text-gray-500 text-sm">Central monitoring station for multiple patients. Real-time Gemini AI agent analysis.</p>
          </button>
        </div>
      </div>
    );
  }

  if (mode === AppMode.WEARABLE) {
    return (
      <WearableInterface 
        currentPatient={currentPatient}
        onToggleSleep={() => {}}
        onToggleScan={() => {}}
        onSimulateAnomaly={() => {
          setPatients(prev => prev.map(p => p.id === activePatientId ? { ...p, vitals: { ...p.vitals, heartRate: 145, stressLevel: 95 } } : p));
        }}
        isEmergency={isEmergency}
        onCancelEmergency={() => { setIsEmergency(false); broadcast('SOS_TRIGGER', false); }}
        onTriggerSOS={() => { setIsEmergency(true); broadcast('SOS_TRIGGER', true); }}
      />
    );
  }

  return (
    <CompanionDashboard 
      patients={patients}
      activePatientId={activePatientId}
      onSwitchPatient={setActivePatientId}
      onAddPatient={(p) => setPatients(prev => [...prev, p])}
      devices={MOCK_DEVICES}
      onTriggerAnalysis={handleTriggerAnalysis}
      isAnalysing={isAnalysing}
    />
  );
};

